package com.blubugtech.bakery_order_service; import java.math.BigDecimal; import java.util.Arrays; import java.util.List; public class TestCalc { public static void main(String[] args) { Integer quantity = 2; BigDecimal unitPrice = new BigDecimal("189.32"); BigDecimal subtotal = Arrays.asList(quantity).stream().map(q -> unitPrice.multiply(BigDecimal.valueOf(q))).reduce(BigDecimal.ZERO, BigDecimal::add); System.out.println(subtotal); } }
